from ansible.utils.unsafe_proxy import (
    AnsibleUnsafeText,
    _wrap_set,
)


def test_wrap_set_wraps_each_member():
    source = {"alpha", "beta", 42}

    wrapped = _wrap_set(source)

    assert wrapped is not source
    assert wrapped == {"alpha", "beta", 42}
    assert {item for item in wrapped if isinstance(item, str)} == {
        "alpha",
        "beta",
    }
    assert all(
        isinstance(item, AnsibleUnsafeText)
        for item in wrapped
        if isinstance(item, str)
    )
    assert 42 in wrapped
